# which labelled decisions each "ambiguous" note is about (the rest of that page's labels are clear)
AMBIGUOUS_FIELDS = {
    "uk-sussex-chancellor": ["nationality"], "nl-leiden-lexs": ["nationality"], "uk-lse-gss": ["nationality"],
    "fr-sciencespo-boutmy": ["deadlines", "funding_class"], "nl-ihe-delft": ["funding_class"], "de-humboldt-fellow": ["nationality"],
    "fi-helsinki-schol": ["funding_class"], "at-ista-phd": ["funding_class", "cycle_status"], "nl-tudelft-effen": ["funding_class"],
    "au-monash-merit": ["nationality"], "ca-toronto-pearson": ["funding_class"], "cn-yenching": ["funding_class"],
    "eg-auc-intl": ["funding_class"], "eu-erasmus-mundus": ["cycle_status", "funding_class"], "us-mitchell": ["nationality", "funding_class"],
    "za-aims": ["funding_class"], "uk-york-gex": ["funding_class"], "uk-nottingham-dsms": ["funding_class"],
    "uk-aberdeen-intl": ["cycle_status"], "de-villigst-intl": ["deadlines", "cycle_status"], "jp-yoneyama": ["cycle_status"],
    "tw-nthu-intl": ["funding_class"], "ca-banting": ["cycle_status"], "ca-trudeau": ["funding_class"],
    "nz-waikato-intl": ["cycle_status"], "us-pdsoros": ["cycle_status"], "us-jkcf-grad": ["funding_class"],
    "uk-lboro-intl": ["nationality"], "ca-concordia-ita": ["nationality"]}
assert set(AMBIGUOUS_FIELDS) == {k for k, v in P.items() if v.get("ambiguous")}, \
    {k for k, v in P.items() if v.get("ambiguous")} ^ set(AMBIGUOUS_FIELDS)
urls = json.loads((L / "urls.json").read_text())
ids = {p["id"] for p in urls["pages"]}
assert set(P) <= ids and not set(P) & set(EXCLUDED), (set(P) - ids, set(P) & set(EXCLUDED))
pages = {}
for p in urls["pages"]:
    pid = p["id"]
    if pid in P:
        p["split"] = "test"
        lab = P[pid]
        pages[pid] = {"kind": "opportunity", "fields": lab["fields"],
                      "evidence": {k: {"quote": v, "url": p["url"]} for k, v in lab["evidence"].items()},
                      "ambiguous": lab.get("ambiguous", ""), "ambiguous_fields": AMBIGUOUS_FIELDS.get(pid, [])}
    else:
        p["split"] = "excluded"
        p["excluded_because"] = EXCLUDED[pid]
(L / "urls.json").write_text(json.dumps(urls, indent=1, ensure_ascii=False) + "\n")
(L / "labels.json").write_text(json.dumps({"today": "2026-10-18", "version": "L-1",
    "note": "programme decisions labelled by hand from the official pages before any extractor ran on them; quotes per field",
    "pages": pages}, indent=1, ensure_ascii=False) + "\n")
print(len(pages), "labelled (all test);", sum(1 for p in urls["pages"] if p["split"] == "excluded"), "excluded")
